const staticData = $getWorkflowStaticData('global');

// เก็บคำถามแรกไว้สำหรับอ้างอิง (ถ้าจำเป็น)
if (!staticData.first_question) {
    staticData.first_question = {
        question: $json["chatInput"],
        sessionId: $json["userId"] || "default-session",
        startTime: new Date().toISOString()
    };
}


// ส่งออกคำถามปัจจุบัน (ไม่ใช่คำถามแรก!)
return [{
    // ส่งคำถามปัจจุบัน
    input: $json["chatInput"],  // ← เปลี่ยนตรงนี้!

    // เก็บข้อมูล session ไว้ (optional)
    sessionId: staticData.first_question.sessionId,

    // เก็บคำถามแรกไว้อ้างอิง (ถ้าต้องการ)
    _metadata: {
        firstQuestion: staticData.first_question.question,
        sessionStartTime: staticData.first_question.startTime
    }
}];

