={{ (function() {
  const paramsString = $fromAI('Tool_Parameters');

  // Default path
  const defaultParams = {
    file_path: "/home/user/document.md"
  };

  if (!paramsString) {
    return defaultParams;
  }

  try {
    // ลองแปลง JSON ก่อน
    const params = JSON.parse(paramsString);
    return {
      file_path: params.file_path || params.path || params.file || defaultParams.file_path
    };
  } catch (e) {
    // ถ้าแปลง JSON ไม่ได้ ถือว่าเป็น path string โดยตรง
    if (typeof paramsString === 'string' && paramsString.trim().length > 0) {
      return {
        file_path: paramsString.trim()
      };
    }
    return defaultParams;
  }
})() }}

